/**
 * The tile our route answers where Plan IGN has none (event-map v11, « Les tuiles »): a PNG of
 * 256 × 256, RGBA of 8 bits, every pixel transparent; 334 bytes, made once and written here.
 */
export const BLANK_TILE: Uint8Array<ArrayBuffer> = Uint8Array.from(
  Buffer.from(
    "",
    "base64",
  ),
);
